s = input().replace(' ', '')
pos = 0
def peek():
    return s[pos] if pos < len(s) else ''
def E():
    global pos
    v = T()
    while peek() == '+':
        pos += 1
        v += T()
    return v
def T():
    global pos
    v = F()
    while peek() == '*':
        pos += 1
        v *= F()
    return v
def F():
    global pos
    if peek() == '(':
        pos += 1
        v = E()
        pos += 1
        return v
    start = pos
    while peek().isdigit():
        pos += 1
    return int(s[start:pos])
