using System;
class Program {
  static void Main() {
    int n = int.Parse(Console.ReadLine());
    string best = ""; int bm = int.MinValue; double sum = 0;
    for (int i = 0; i < n; i++) {
      var p = Console.ReadLine().Split(',');
      int m = int.Parse(p[1]); sum += m;
      if (m > bm) { bm = m; best = p[0]; }
    }
    Console.WriteLine($"{best} {sum / n:F2}");
  }
}

