def broadcast_shape(s1, s2):
    n = max(len(s1), len(s2))
    a = (1,) * (n - len(s1)) + tuple(s1)
    b = (1,) * (n - len(s2)) + tuple(s2)
    out = []
    for x, y in zip(a, b):
        if x == y or x == 1 or y == 1:
            out.append(max(x, y))
        else:
            return None
    return tuple(out)
print(broadcast_shape((1000, 5), (5,)), broadcast_shape((3, 1), (1, 4)), broadcast_shape((3, 4), (3,)))

